#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/toolchain.h>

/*
 * This test verifies the functionality of iterable sections.
 * It defines several items and places them into different sections
 * (RAM, ROM, etc.) and then iterates over them to verify their content.
 */

struct test_item {
    int val;
};

/* Items for RAM section */
static const struct test_item __attribute__((section(".ram_section"))) item_ram_1 = {1};
static const struct test_item __attribute__((section(".ram_section"))) item_ram_2 = {2};
static const struct test_item __attribute__((section(".ram_section"))) item_ram_3 = {3};
static const struct test_item __attribute__((section(".ram_section"))) item_ram_4 = {4};

/* Items for ROM section (example, not directly related to the error) */
static const struct test_item __attribute__((section(".rom_section"))) item_rom_1 = {10};
static const struct test_item __attribute__((section(".rom_section"))) item_rom_2 = {20};

/* Expected values */
// FIX: Corrected RAM_EXPECT to include all 4 items in the .ram_section
#define RAM_EXPECT (1 + 2 + 3 + 4)
#define ROM_EXPECT (10 + 20)

/*
 * Test function for RAM iterable section.
 * Iterates over items in .ram_section and sums their values.
 */
static void iterable_sections_test_ram(void)
{
    int out = 0;
    Z_ITERABLE_SECTION_FOREACH(struct test_item, item, .ram_section) {
        out += item->val;
    }
    zassert_equal(out, RAM_EXPECT, "out not equal to RAM_EXPECT");
}

/*
 * Test function for ROM iterable section.
 * Iterates over items in .rom_section and sums their values.
 */
static void iterable_sections_test_rom(void)
{
    int out = 0;
    Z_ITERABLE_SECTION_FOREACH(struct test_item, item, .rom_section) {
        out += item->val;
    }
    zassert_equal(out, ROM_EXPECT, "out not equal to ROM_EXPECT");
}

ZTEST_SUITE(iterable_sections, NULL, NULL, NULL, NULL, NULL);

ZTEST(iterable_sections, test_ram)
{
    iterable_sections_test_ram();
}

ZTEST(iterable_sections, test_rom)
{
    iterable_sections_test_rom();
}
